}
secret_exists() {
  local found
  if ! found=$(kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" get secret "$1" --ignore-not-found -o name); then
    die "Could not inspect Secret name $1 in $CLIPP_TEST_NAMESPACE."
  fi
  [[ -n "$found" ]]
}

load_database_target() {
if grep -Eq 'example\.test|operator-namespace|operator-attested|sha256:aaaaaaaa|sha256:bbbbbbbb|ocid1\..*example|longhorn-retain' "$CLIPP_TEST_VALUES_FILE"; then
  die "Placeholder values remain. Edit the private values file and rerun."
fi
command -v helm >/dev/null 2>&1 || die "Helm is required to validate the chart."
[[ "$CLIPP_TEST_NAMESPACE" == relay-portal-test ]] || die "Bundled PostgreSQL is restricted to relay-portal-test."
db_fields=$(ruby -ryaml -e '
  v = YAML.safe_load(File.read(ARGV.fetch(0)))
  abort "bundled database mode required" unless v.dig("database", "mode") == "bundled"
  abort "initial values must keep the relay stopped" unless v.dig("deployment", "phase") == "stopped"
  abort "first initialization must be explicit" unless v.dig("database", "bundled", "initialize") == true
  fields = [v.dig("database", "name"), v.dig("database", "bundled", "clusterDomain"), v.dig("database", "bundled", "adminSecret"), v.dig("database", "servingSecret"), v.dig("database", "migrationSecret"), v.dig("database", "bundled", "tlsSecret"), v.dig("database", "caSecret")]
  abort "database name, domain and five Secret names must be present" unless fields.all? { |item| item.is_a?(String) && !item.empty? && item !~ /\s/ }
  puts fields.join(" ")
' "$CLIPP_TEST_VALUES_FILE") || die "Could not read the database target from the values file."
read -r db_name db_domain db_admin_secret db_serving_secret db_migration_secret db_tls_secret db_ca_secret <<< "$db_fields"
require_match "database name" "$db_name" '^[a-z][a-z0-9_]{0,62}$'
require_match "cluster DNS domain" "$db_domain" '^[a-z0-9.-]+$'
for name in "$db_admin_secret" "$db_serving_secret" "$db_migration_secret" "$db_tls_secret" "$db_ca_secret"; do require_match "database Secret name" "$name" '^[a-z0-9]([-a-z0-9]*[a-z0-9])?$'; done
[[ $(printf '%s\n' "$db_admin_secret" "$db_serving_secret" "$db_migration_secret" "$db_tls_secret" "$db_ca_secret" | sort -u | wc -l | tr -d ' ') == 5 ]] || die "The five database Secret names must differ."
pg_host=$(helm template "$CLIPP_TEST_RELEASE" "$CLIPP_TEST_GO_REPO/charts/clipp-relay" -n "$CLIPP_TEST_NAMESPACE" -f "$CLIPP_TEST_VALUES_FILE" -f "$letsencrypt_overlay" | ruby -ryaml -rjson -e '
  docs = YAML.load_stream(STDIN.read).compact
  c = docs.find { |d| d["kind"] == "ConfigMap" && d.dig("metadata", "name").end_with?("-config") }
  abort "relay ConfigMap missing" unless c
  puts JSON.parse(c.dig("data", "config.json")).dig("database", "host")
') || die "Could not render the exact PostgreSQL Service hostname."
[[ "$pg_host" == "$CLIPP_TEST_RELEASE-clipp-relay-postgres.$CLIPP_TEST_NAMESPACE.svc.$db_domain" ]] || die "Rendered PostgreSQL hostname does not match this release and cluster domain."
}
load_saved_setup() {
  require_file "$ENV_FILE"
  local key
  for key in CLIPP_TEST_PORTAL_ORIGIN CLIPP_TEST_WSS_HOSTNAME CLIPP_TEST_KUBE_CONTEXT CLIPP_TEST_NAMESPACE CLIPP_TEST_RELEASE CLIPP_TEST_GO_REPO CLIPP_TEST_BUNDLED_VALUES_FILE CLIPP_TEST_ADMIN_EMAIL CLIPP_TEST_USER_EMAIL CLIPP_TEST_EXTENSION_ID; do
    printf -v "$key" '%s' "$(_existing "$key" || true)"
    [[ -n "${!key}" ]] || die "Saved $key is missing; run the wizard from step 1 to complete setup."
  done
  CLIPP_TEST_VALUES_FILE="$CLIPP_TEST_BUNDLED_VALUES_FILE"
  [[ "$CLIPP_TEST_VALUES_FILE" == /* && "$CLIPP_TEST_GO_REPO" == /* ]] || die "Saved chart and values paths must be absolute."
  require_file "$CLIPP_TEST_VALUES_FILE"
  letsencrypt_overlay="$CLIPP_TEST_GO_REPO/charts/clipp-relay/examples/letsencrypt-values.yaml"
  require_file "$letsencrypt_overlay"
  for cmd in kubectl helm ruby python3 openssl git; do command -v "$cmd" >/dev/null 2>&1 || die "$cmd is required to resume."; done
  require_match "saved portal origin" "$CLIPP_TEST_PORTAL_ORIGIN" '^https://[a-z0-9][a-z0-9.-]+$'
  CLIPP_TEST_PORTAL_HOST="${CLIPP_TEST_PORTAL_ORIGIN#https://}"
  require_match "saved WSS host" "$CLIPP_TEST_WSS_HOSTNAME" '^[a-z0-9][a-z0-9.-]+$'
  require_match "saved namespace" "$CLIPP_TEST_NAMESPACE" '^[a-z0-9]([-a-z0-9]*[a-z0-9])?$'
  require_match "saved release" "$CLIPP_TEST_RELEASE" '^[a-z0-9]([-a-z0-9]*[a-z0-9])?$'
  require_match "saved extension ID" "$CLIPP_TEST_EXTENSION_ID" '^[a-p]{32}$'
  [[ "$CLIPP_TEST_PORTAL_HOST" != "$CLIPP_TEST_WSS_HOSTNAME" ]] || die "Saved portal and WSS hosts must differ."
  kubectl config get-contexts -o name | grep -Fxq "$CLIPP_TEST_KUBE_CONTEXT" || die "Saved context is absent from kubeconfig."
  kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" get namespace "$CLIPP_TEST_NAMESPACE" -o name >/dev/null || die "Saved test namespace is unavailable."
  load_database_target
  ruby -ryaml -e '
    v = YAML.safe_load(File.read(ARGV.fetch(0)))
    abort "saved public hosts differ from reviewed values" unless v.dig("public", "portalOrigin") == ARGV.fetch(1) && v.dig("public", "wssHostname") == ARGV.fetch(2)
  ' "$CLIPP_TEST_VALUES_FILE" "$CLIPP_TEST_PORTAL_ORIGIN" "$CLIPP_TEST_WSS_HOSTNAME" || die "Saved configuration differs from chart values."
  local names
  names=$(ruby -ryaml -e '
    v = YAML.safe_load(File.read(ARGV.fetch(0)))
    names = %w[googleSecret adminSecret pepperSecret journalSecret].map { |k| v.fetch("credentials").fetch(k) }
    abort "application Secret names must differ" unless names.uniq.length == 4
    names.each { |n| abort "invalid Secret name" unless n.match?(/\A[a-z0-9]([-a-z0-9]*[a-z0-9])?\z/) }
    puts names
  ' "$CLIPP_TEST_VALUES_FILE") || die "Could not restore application Secret names."
  while IFS= read -r key; do secret_exists "$key" || die "Application Secret $key is missing; complete its setup before resuming."; done <<< "$names"
  for key in "$db_admin_secret" "$db_serving_secret" "$db_migration_secret" "$db_tls_secret" "$db_ca_secret"; do
    secret_exists "$key" || die "Database Secret $key is missing; complete steps 8–10 before resuming."
  done
  say "Resuming at step $START_AT using saved target: $CLIPP_TEST_KUBE_CONTEXT / $CLIPP_TEST_NAMESPACE, release $CLIPP_TEST_RELEASE."
  say "Earlier setup stages are skipped. Saved chart identity and installed prerequisites are verified before continuing."
  confirm "Resume this saved isolated target at step $START_AT?" || die "Resume cancelled."
}

