if [[ "$new_values_file" == 1 ]]; then
  python3 - "$CLIPP_TEST_VALUES_FILE" "$journal_config_file" "$CLIPP_TEST_PORTAL_ORIGIN" "$CLIPP_TEST_WSS_HOSTNAME" "$CLIPP_TEST_EXTENSION_REDIRECT" "$CLIPP_TEST_GOOGLE_SECRET_NAME" "$CLIPP_TEST_ADMIN_SECRET_NAME" "$CLIPP_TEST_PEPPER_SECRET_NAME" "$CLIPP_TEST_JOURNAL_SECRET_NAME" <<'PY'
import json, re, sys
from pathlib import Path

values_path = Path(sys.argv[1])
with open(sys.argv[2], encoding='utf-8') as source:
    journal = json.load(source)['journal']
replacement = {
    ('public', 'portalOrigin'): sys.argv[3],
    ('public', 'wssHostname'): sys.argv[4],
    ('clients', 'androidRedirect'): 'clipp-relay://oauth/callback',
    ('clients', 'extensionRedirect'): sys.argv[5],
    ('credentials', 'googleSecret'): sys.argv[6],
    ('credentials', 'adminSecret'): sys.argv[7],
    ('credentials', 'pepperSecret'): sys.argv[8],
    ('credentials', 'journalSecret'): sys.argv[9],
}
for yaml_key, config_key in {
    'region': 'region', 'namespace': 'namespace', 'bucket': 'bucket',
    'repositoryId': 'repository_id', 'coverageFloor': 'coverage_floor',
    'coverageHash': 'coverage_hash', 'tenancyOcid': 'tenancy_ocid',
    'userOcid': 'user_ocid', 'fingerprint': 'fingerprint',
}.items():
    replacement[('journal', yaml_key)] = journal[config_key]
text = values_path.read_text(encoding='utf-8')
section = None
found = set()
output = []
for line in text.splitlines(keepends=True):
    top = re.fullmatch(r'([A-Za-z][A-Za-z0-9]*):\s*\n?', line)
    if top:
        section = top.group(1)
    field = re.match(r'^  ([A-Za-z][A-Za-z0-9]*):', line)
    key = (section, field.group(1)) if field else None
    if key in replacement:
        line = f'  {key[1]}: {json.dumps(replacement[key])}\n'
        found.add(key)
    output.append(line)
missing = set(replacement) - found
if missing:
    raise SystemExit(f'Chart example changed; missing fields: {sorted(missing)}')
text = ''.join(output).replace('/dns4/wss.example.test/tcp/443/tls/ws', f'/dns4/{sys.argv[4]}/tcp/443/tls/ws')
values_path.write_text(text, encoding='utf-8')
PY
  say "Copied the chart example and filled hosts, callbacks, Secret names, and journal attestation from earlier stages."
fi
