confirm "Are these the database, hostname and five Secret names for this test release?" || die "Correct the values file before creating credentials."

stage "Prepare separate PostgreSQL login files"
say "Three database roles need separate passwords. The administrator initializes PostgreSQL; the serving role runs the relay; the migration role changes schema. These files stay outside Git and no password is printed."
db_secret_dir="$TEST_DIR/postgres"
[[ ! -L "$db_secret_dir" ]] || die "Database credential directory cannot be a symbolic link."
mkdir -p "$db_secret_dir"
chmod 700 "$db_secret_dir"
prepare_role() {
  local role_dir="$db_secret_dir/$1" expected_user="$2" existing_user
  [[ ! -L "$role_dir" ]] || die "Database role directory cannot be a symbolic link: $role_dir"
  mkdir -p "$role_dir"
  chmod 700 "$role_dir"
  [[ ! -L "$role_dir/username" && ! -L "$role_dir/password" ]] || die "Refusing a symbolic link in $role_dir."
  if [[ -e "$role_dir/username" ]]; then
    existing_user=$(cat "$role_dir/username")
    [[ "$existing_user" == "$expected_user" ]] || die "Existing $1 username differs; review the file before rerunning."
  else
    printf '%s\n' "$expected_user" > "$role_dir/username"
  fi
  if [[ ! -e "$role_dir/password" ]]; then
    python3 - "$role_dir/password" <<'PY'
import os, secrets, sys
path = sys.argv[1]
fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
with os.fdopen(fd, 'w', encoding='ascii') as target:
    target.write(secrets.token_urlsafe(48) + '\n')
PY
  fi
  [[ -s "$role_dir/password" ]] || die "Empty $1 password file."
  chmod 600 "$role_dir/username" "$role_dir/password"
  say "Ready local $1 login files for $expected_user; password reused if already present."
}
prepare_role admin postgres
prepare_role serving clipp_serving
prepare_role migration clipp_migration
write_env CLIPP_TEST_DB_ADMIN_DIR "$db_secret_dir/admin"
write_env CLIPP_TEST_DB_SERVING_DIR "$db_secret_dir/serving"
write_env CLIPP_TEST_DB_MIGRATION_DIR "$db_secret_dir/migration"

stage "Create the internal PostgreSQL TLS files"
say "PostgreSQL uses its own internal certificate. Let's Encrypt is for the public portal and WSS hosts. The database certificate must name the exact internal Service shown below."
say "Internal Service name: $pg_host"
command -v openssl >/dev/null 2>&1 || die "OpenSSL is required to create and verify the internal database certificate."
db_tls_dir="$db_secret_dir/tls-bundle"
[[ ! -L "$db_tls_dir" ]] || die "Database TLS bundle cannot be a symbolic link."
if [[ ! -e "$db_tls_dir" ]]; then
  tls_tmp=$(mktemp -d "$db_secret_dir/.tls.XXXXXX")
  trap 'rm -rf "$tls_tmp"' EXIT
  chmod 700 "$tls_tmp"
  openssl req -new -x509 -newkey rsa:3072 -noenc -sha256 -days 180 \
    -subj '/CN=Clipp Relay Test PostgreSQL CA' \
    -addext 'basicConstraints=critical,CA:TRUE,pathlen:0' \
    -addext 'keyUsage=critical,keyCertSign,cRLSign' \
    -keyout "$tls_tmp/ca.key" -out "$tls_tmp/ca.crt" >/dev/null 2>&1 || die "Could not create the test database CA."
  openssl req -new -newkey rsa:3072 -noenc -sha256 \
    -subj '/CN=clipp-test-postgres' -keyout "$tls_tmp/server.key" -out "$tls_tmp/server.csr" >/dev/null 2>&1 || die "Could not create the database server key and request."
  cat > "$tls_tmp/server.ext" <<EOF
basicConstraints=critical,CA:FALSE
keyUsage=critical,digitalSignature,keyEncipherment
extendedKeyUsage=serverAuth
subjectAltName=DNS:$pg_host
EOF
  openssl x509 -req -sha256 -days 90 -in "$tls_tmp/server.csr" \
    -CA "$tls_tmp/ca.crt" -CAkey "$tls_tmp/ca.key" -CAcreateserial \
    -extfile "$tls_tmp/server.ext" -out "$tls_tmp/server.crt" >/dev/null 2>&1 || die "Could not sign the database server certificate."
  chmod 600 "$tls_tmp"/*
  mv "$tls_tmp" "$db_tls_dir" || die "Could not save the database TLS bundle."
  trap - EXIT
  say "Created a local test CA and a server certificate; the CA private key will not enter Kubernetes."
else
  [[ -d "$db_tls_dir" && ! -L "$db_tls_dir" ]] || die "Database TLS bundle path is not a normal directory."
  say "Reusing the existing database TLS bundle; no certificate or key was replaced."
fi
for file in ca.key ca.crt server.key server.crt; do
  [[ ! -L "$db_tls_dir/$file" ]] || die "Refusing a symbolic link in the database TLS bundle: $file"
  require_file "$db_tls_dir/$file"
done
openssl x509 -in "$db_tls_dir/ca.crt" -noout -checkend 604800 >/dev/null 2>&1 || die "Database CA expires within seven days; arrange a reviewed rotation."
openssl x509 -in "$db_tls_dir/server.crt" -noout -checkhost "$pg_host" >/dev/null 2>&1 || die "Server certificate does not match $pg_host."
openssl verify -purpose sslserver -CAfile "$db_tls_dir/ca.crt" "$db_tls_dir/server.crt" >/dev/null 2>&1 || die "Server certificate does not verify against the local CA."
openssl x509 -in "$db_tls_dir/server.crt" -noout -checkend 604800 >/dev/null 2>&1 || die "Server certificate expires within seven days; arrange a reviewed rotation."
ca_cert_key=$(openssl x509 -in "$db_tls_dir/ca.crt" -pubkey -noout | openssl pkey -pubin -outform DER | openssl dgst -sha256)
ca_file_key=$(openssl pkey -in "$db_tls_dir/ca.key" -pubout -outform DER | openssl dgst -sha256)
[[ "$ca_cert_key" == "$ca_file_key" ]] || die "Local CA private key does not match its certificate."
server_cert_key=$(openssl x509 -in "$db_tls_dir/server.crt" -pubkey -noout | openssl pkey -pubin -outform DER | openssl dgst -sha256)
server_file_key=$(openssl pkey -in "$db_tls_dir/server.key" -pubout -outform DER | openssl dgst -sha256)
[[ "$server_cert_key" == "$server_file_key" ]] || die "Server private key does not match its certificate."
chmod 700 "$db_tls_dir"
chmod 600 "$db_tls_dir/ca.key" "$db_tls_dir/ca.crt" "$db_tls_dir/server.key" "$db_tls_dir/server.crt"
write_env CLIPP_TEST_DB_CA_FILE "$db_tls_dir/ca.crt"
write_env CLIPP_TEST_DB_SERVER_CERT_FILE "$db_tls_dir/server.crt"
write_env CLIPP_TEST_DB_SERVER_KEY_FILE "$db_tls_dir/server.key"
say "Verified the certificate name, CA chain, key match and remaining validity."

stage "Create the five PostgreSQL Kubernetes Secrets"
say "Target: $CLIPP_TEST_KUBE_CONTEXT / $CLIPP_TEST_NAMESPACE. The wizard creates only missing names. It never replaces an existing Secret."
db_missing=()
db_existing=()
for name in "$db_admin_secret" "$db_serving_secret" "$db_migration_secret" "$db_tls_secret" "$db_ca_secret"; do
  if secret_exists "$name"; then db_existing+=("$name"); else db_missing+=("$name"); fi
done
if (( ${#db_existing[@]} )); then
  say "Existing names will be left untouched: ${db_existing[*]}"
  confirm "Do those existing Secret objects belong to this test and match the reviewed local files?" || die "Choose new versioned names or ask the operator to resolve the mismatch."
fi
if (( ${#db_missing[@]} )); then
  say "Missing names to create: ${db_missing[*]}"
  say "The administrator, serving and migration Secrets receive username/password files. The server TLS Secret receives tls.crt/tls.key. The CA Secret receives only ca.crt."
  confirm "Create these missing five-role Secret resources in this exact test namespace?" || die "No database Secret was created by this stage."
  if ! secret_exists "$db_admin_secret"; then kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" create secret generic "$db_admin_secret" --from-file=username="$db_secret_dir/admin/username" --from-file=password="$db_secret_dir/admin/password" || die "Administrator Secret creation failed; inspect the namespace and rerun."; fi
  if ! secret_exists "$db_serving_secret"; then kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" create secret generic "$db_serving_secret" --from-file=username="$db_secret_dir/serving/username" --from-file=password="$db_secret_dir/serving/password" || die "Serving Secret creation failed; inspect the namespace and rerun."; fi
  if ! secret_exists "$db_migration_secret"; then kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" create secret generic "$db_migration_secret" --from-file=username="$db_secret_dir/migration/username" --from-file=password="$db_secret_dir/migration/password" || die "Migration Secret creation failed; inspect the namespace and rerun."; fi
  if ! secret_exists "$db_tls_secret"; then kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" create secret tls "$db_tls_secret" --cert="$db_tls_dir/server.crt" --key="$db_tls_dir/server.key" || die "PostgreSQL TLS Secret creation failed; inspect the namespace and rerun."; fi
  if ! secret_exists "$db_ca_secret"; then kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" create secret generic "$db_ca_secret" --from-file=ca.crt="$db_tls_dir/ca.crt" || die "PostgreSQL CA Secret creation failed; inspect the namespace and rerun."; fi
fi
for name in "$db_admin_secret" "$db_serving_secret" "$db_migration_secret" "$db_tls_secret" "$db_ca_secret"; do secret_exists "$name" || die "Database Secret is still absent: $name"; done
say "All five database Secret names exist. Existing Secret contents were not read or replaced."

stage "Run read-only chart and cluster preflight"
say "This wizard skips NetworkPolicy enforcement validation as requested. The chart still renders policy objects, and the preflight may list enforcement as pending; that message does not stop this wizard."
say "The preflight checks the chart, issuer, IngressClass, Secret names, StorageClass and PVC name. It does not read Secret contents or install resources."
if helm --kube-context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" status "$CLIPP_TEST_RELEASE" >/dev/null 2>&1; then
  say "This release already exists. The first-install preflight would reject its existing PVC; the installation stages below verify its saved identity and resume the exact phase."
else
  bash "$CLIPP_TEST_GO_REPO/scripts/preflight-bundled-test.sh" "$CLIPP_TEST_VALUES_FILE" "$CLIPP_TEST_RELEASE" "$CLIPP_TEST_NAMESPACE" "$CLIPP_TEST_KUBE_CONTEXT" "$letsencrypt_overlay" || die "Read-only preflight failed."
fi
confirm "Do the rendered hosts, callbacks, Secret names, image digest and journal attestation match this test target?" || die "Correct the values before installation."

else
  load_saved_setup
  _STAGE_INDEX=$((START_AT - 1))
fi

chart_dir="$CLIPP_TEST_GO_REPO/charts/clipp-relay"
pg_sts_name="${pg_host%%.*}"
relay_sts_name="$CLIPP_TEST_RELEASE-clipp-relay"
db_run_id=$(_existing CLIPP_TEST_DB_RUN_ID || true)
if [[ -n "$db_run_id" ]]; then require_match "saved database run ID" "$db_run_id" '^[a-f0-9]{8}$'; fi
# The installed chart identity survives source-only consolidation changes.
# Require identical chart trees or identical rendered resources for this target.
chart_baseline_commit=$(_existing CLIPP_TEST_CHART_BASELINE_COMMIT || true)
if [[ -z "$chart_baseline_commit" ]]; then chart_baseline_commit=$(git -C "$CLIPP_TEST_GO_REPO" rev-parse HEAD); fi
require_match "chart baseline commit" "$chart_baseline_commit" '^[a-f0-9]{40}$'
baseline_chart_tree=$(git -C "$CLIPP_TEST_GO_REPO" rev-parse --verify "${chart_baseline_commit}:charts/clipp-relay") || die "Could not resolve the saved chart baseline; verify the commit and chart path before resuming."
current_chart_tree=$(git -C "$CLIPP_TEST_GO_REPO" rev-parse --verify HEAD:charts/clipp-relay) || die "Could not resolve the current chart; verify the checkout and chart path before resuming."
if [[ "$baseline_chart_tree" != "$current_chart_tree" ]]; then
  # Source-only changes may preserve this installed target. Compare every phase
  # with the saved inputs; keep the original installation fingerprint below.
  python3 - "$CLIPP_TEST_GO_REPO" "$chart_baseline_commit" "$CLIPP_TEST_VALUES_FILE" "$letsencrypt_overlay" "$CLIPP_TEST_RELEASE" "$CLIPP_TEST_NAMESPACE" "$db_run_id" <<'PY_CHART_COMPATIBILITY'
import json, pathlib, subprocess, sys, tempfile

repo, baseline, values, overlay, release, namespace, run_id = sys.argv[1:]
current_chart = pathlib.Path(repo) / 'charts/clipp-relay'

def checked(command, label, input=None):
    result = subprocess.run(command, input=input, capture_output=True)
    if result.returncode:
        raise SystemExit('Chart compatibility check failed: ' + label)
    return result.stdout

def resources(chart, flags, label):
    rendered = checked(['helm', 'template', release, str(chart), '-n', namespace,
                        '-f', values, '-f', overlay] + flags, label + ' render')
    parsed = checked(['ruby', '-ryaml', '-rjson', '-e',
                      'puts JSON.generate(YAML.load_stream(STDIN.read).compact)'],
                     label + ' YAML parsing', rendered)
    return json.loads(parsed)

phases = [
    ('saved defaults', []),
    ('stopped', ['--set', 'deployment.phase=stopped', '--set-string',
                 'deployment.runId=', '--set', 'database.bundled.initialize=true']),
    ('migrating', ['--set', 'deployment.phase=migrating', '--set-string',
                   'deployment.runId=' + (run_id or '1234abcd'), '--set',
                   'database.bundled.initialize=false']),
    ('serving', ['--set', 'deployment.phase=serving', '--set-string',
                 'deployment.runId=', '--set', 'database.bundled.initialize=false']),
]
with tempfile.TemporaryDirectory(prefix='clipp-chart-compatibility-') as directory:
    archive = checked(['git', '-C', repo, 'archive', baseline, 'charts/clipp-relay'],
                      'saved chart extraction')
    checked(['tar', '-xf', '-', '-C', directory], 'saved chart extraction', archive)
    baseline_chart = pathlib.Path(directory) / 'charts/clipp-relay'
    for phase, flags in phases:
        for upgrade in (False, True):
            mode = 'upgrade' if upgrade else 'install'
            render_flags = flags + (['--is-upgrade'] if upgrade else [])
            label = phase + ' ' + mode
            if resources(baseline_chart, render_flags, 'baseline ' + label) != resources(current_chart, render_flags, 'current ' + label):
                raise SystemExit('Consolidated chart differs from the installed chart baseline in ' + label + '; review the changed resources before resuming.')
PY_CHART_COMPATIBILITY
  [[ $? == 0 ]] || die "Chart compatibility could not be verified; review the chart before resuming."
  say "Chart source changed, but rendered resources match the saved baseline for every install and upgrade phase. Keeping the original installation identity."
fi
WORK_DIR=$(_existing CLIPP_TEST_WORK_DIR || true)
if [[ -z "$WORK_DIR" ]]; then WORK_DIR="$TEST_DIR/work"; fi
[[ "$WORK_DIR" == /* && ! -L "$WORK_DIR" ]] || die "Wizard work directory must be an absolute non-symlink path."
mkdir -p "$WORK_DIR"
chmod 700 "$WORK_DIR"
install_fingerprint=$(python3 - "$CLIPP_TEST_GO_REPO" "$CLIPP_TEST_VALUES_FILE" "$letsencrypt_overlay" "$chart_baseline_commit" <<'PY'
import hashlib, pathlib, subprocess, sys
digest = hashlib.sha256()
digest.update(subprocess.check_output(['git', '-C', sys.argv[1], 'rev-parse', sys.argv[4]]).strip())
for path in sys.argv[2:4]:
    digest.update(pathlib.Path(path).read_bytes())
print(digest.hexdigest())
PY
) || die "Could not fingerprint the chart and reviewed values."
saved_fingerprint=$(_existing CLIPP_TEST_INSTALL_FINGERPRINT || true)
migration_values_file="$CLIPP_TEST_VALUES_FILE"
[[ -z "$saved_fingerprint" || "$saved_fingerprint" == "$install_fingerprint" ]] || die "Chart commit or values changed since installation began. Review the change before resuming."
[[ -z "$(git -C "$CLIPP_TEST_GO_REPO" status --porcelain -- charts/clipp-relay)" ]] || die "The install chart has uncommitted changes; use the reviewed committed chart."

release_status() {
  helm --kube-context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" list --filter "^$CLIPP_TEST_RELEASE$" -o json | ruby -rjson -e '
    matches = JSON.parse(STDIN.read).select { |r| r["name"] == ARGV.fetch(0) }
    abort "duplicate Helm release names" if matches.length > 1
    puts(matches.empty? ? "absent" : matches.fetch(0).fetch("status"))
  ' "$CLIPP_TEST_RELEASE"
}
release_phase() {
  helm --kube-context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" get values "$CLIPP_TEST_RELEASE" -o json | ruby -rjson -e '
    values = JSON.parse(STDIN.read)
    deployment = values.fetch("deployment")
    database = values.fetch("database").fetch("bundled")
    puts [deployment.fetch("phase"), deployment.fetch("runId", ""), database.fetch("initialize")].join("|")
  '
}
# Explicitly approved isolated-test profile; canonical chart and values stay intact.
source_chart_dir="$chart_dir"
chart_dir=$(mktemp -d $WORK_DIR/clipp-relay-300m-chart.XXXXXX)
python3 "$CLIPP_TEST_GO_REPO/scripts/prepare-isolated-test-chart.py" "$source_chart_dir" "$chart_dir"
[[ $? == 0 ]] || die "Could not prepare the approved 300m isolated test chart."
# The original install fingerprint continues identifying the baseline chart/values.
# The explicit CPU override is checked in generated and installed Pod specifications.

assert_minimum_node_cpu() {
  local requirements
  requirements=$(helm template "$CLIPP_TEST_RELEASE" "$chart_dir" -n "$CLIPP_TEST_NAMESPACE" -f "$CLIPP_TEST_VALUES_FILE" -f "$letsencrypt_overlay" --set deployment.phase=serving --set-string deployment.runId= --set database.bundled.initialize=false | ruby -ryaml -rjson -e '
    def milli(value)
      text = value.to_s
      text.end_with?("m") ? Float(text.chop).ceil : (Float(text) * 1000).ceil
    end
    docs = YAML.load_stream(STDIN.read).compact
    requirements = docs.select { |d| d["kind"] == "StatefulSet" }.map do |d|
      pod = d.dig("spec", "template", "spec")
      app = pod.fetch("containers").map { |c| milli(c.dig("resources", "requests", "cpu") || "0") }.inject(0, :+)
      init = pod.fetch("initContainers", []).map { |c| milli(c.dig("resources", "requests", "cpu") || "0") }.max || 0
      {"name" => d.dig("metadata", "name"), "cpu" => [app, init].max, "selector" => pod.fetch("nodeSelector", {})}
    end
    abort "rendered Pod CPU requirements missing" if requirements.empty?
    puts JSON.generate(requirements)
  ') || die "Could not render the minimum Pod CPU requirements."
  kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" get nodes -o json | ruby -rjson -e '
    def milli(value)
      text = value.to_s
      text.end_with?("m") ? Float(text.chop).floor : (Float(text) * 1000).floor
    end
    nodes = JSON.parse(STDIN.read).fetch("items")
    requirements = JSON.parse(ARGV.fetch(0))
    requirements.each do |request|
      eligible = nodes.select do |node|
        labels = node.dig("metadata", "labels") || {}
        !node.dig("spec", "unschedulable") && request.fetch("selector").all? { |k, v| labels[k] == v } &&
          node.dig("status", "conditions").any? { |c| c["type"] == "Ready" && c["status"] == "True" }
      end
      unless eligible.any? { |node| milli(node.dig("status", "allocatable", "cpu")) >= request.fetch("cpu") }
        available = eligible.map { |n| "#{n.dig("metadata", "name")}=#{n.dig("status", "allocatable", "cpu")}" }.join(", ")
        abort "#{request.fetch("name")} requests #{request.fetch("cpu")}m CPU, but no matching Ready node has that much allocatable CPU (#{available.empty? ? "none" : available})."
      end
    end
  ' "$requirements" || die "The chart cannot fit this cluster node size. Review node size and the approved test profile before continuing."
}
assert_free_relay_cpu() {
  local capacity_dir
  capacity_dir=$(mktemp -d $WORK_DIR/clipp-relay-cpu-check.XXXXXX)
  kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" get nodes -o json > "$capacity_dir/nodes.json" || die "Could not read node capacity."
  kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" get pods -A -o json > "$capacity_dir/pods.json" || die "Could not read Pod CPU reservations."
  helm template "$CLIPP_TEST_RELEASE" "$chart_dir" -n "$CLIPP_TEST_NAMESPACE" -f "$CLIPP_TEST_VALUES_FILE" -f "$letsencrypt_overlay" --set deployment.phase=serving --set-string deployment.runId= --set database.bundled.initialize=false | ruby -ryaml -rjson -e '
    d = YAML.load_stream(STDIN.read).compact.find { |x| x["kind"] == "StatefulSet" && x.dig("metadata", "name") == ARGV.fetch(0) }
    abort "relay StatefulSet missing" unless d
    puts JSON.generate(d.dig("spec", "template", "spec"))
  ' "$relay_sts_name" > "$capacity_dir/relay.json" || die "Could not render the approved relay profile."
  python3 - "$capacity_dir" "$CLIPP_TEST_NAMESPACE" "$relay_sts_name" <<'PY_CAPACITY'
import json, pathlib, sys
from decimal import Decimal
root = pathlib.Path(sys.argv[1])
nodes = json.loads((root / 'nodes.json').read_text())['items']
pods = json.loads((root / 'pods.json').read_text())['items']
relay = json.loads((root / 'relay.json').read_text())
def milli(value):
    text = str(value)
    for suffix, factor in [('m', '1'), ('u', '0.001'), ('n', '0.000001')]:
        if text.endswith(suffix): return Decimal(text[:-1]) * Decimal(factor)
    return Decimal(text) * 1000
def cpu_request(spec):
    def request(container): return milli(container.get('resources', {}).get('requests', {}).get('cpu', '0'))
    regular = sum((request(c) for c in spec.get('containers', [])), Decimal(0))
    sidecars = Decimal(0)
    initialization = Decimal(0)
    for container in spec.get('initContainers', []):
        if container.get('restartPolicy') == 'Always':
            sidecars += request(container)
            initialization = max(initialization, sidecars)
        else: initialization = max(initialization, sidecars + request(container))
    return max(regular + sidecars, initialization) + milli(spec.get('overhead', {}).get('cpu', '0'))
needed = cpu_request(relay)
if needed != 300: raise SystemExit('Rendered relay must request exactly 300m CPU')
fits = False
for node in nodes:
    labels = node['metadata'].get('labels', {})
    if node.get('spec', {}).get('unschedulable'): continue
    if not any(c['type'] == 'Ready' and c['status'] == 'True' for c in node['status']['conditions']): continue
    if not all(labels.get(k) == v for k, v in relay.get('nodeSelector', {}).items()): continue
    name = node['metadata']['name']
    reserved = Decimal(0)
    for pod in pods:
        if pod['spec'].get('nodeName') != name or pod['status'].get('phase') in ['Succeeded', 'Failed']: continue
        # A resumed serving Pod already occupies the budget being checked.
        if pod['metadata']['namespace'] == sys.argv[2] and pod['metadata']['name'] == sys.argv[3] + '-0': continue
        reserved += cpu_request(pod['spec'])
    free = milli(node['status']['allocatable']['cpu']) - reserved
    print(f'{name}: {free}m CPU unreserved; test profile requires {needed}m')
    fits |= free >= needed
if not fits: raise SystemExit('No matching Ready node currently has 300m unreserved CPU')
PY_CAPACITY
  local capacity_result=$?
  rm -r "$capacity_dir"
  [[ "$capacity_result" == 0 ]] || die "Insufficient CPU reservations for the 300m profile; inspect workloads before continuing."
}

assert_old_relay_absent() {
  kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" get nodes -o json | ruby -rjson -e '
    nodes = JSON.parse(STDIN.read).fetch("items")
    abort "no cluster nodes found" if nodes.empty?
    bad = nodes.reject { |n| n.fetch("status").fetch("conditions").any? { |c| c["type"] == "Ready" && c["status"] == "True" } }
    abort "a cluster node is not Ready; old-process absence cannot be established" unless bad.empty?
  ' || die "Node readiness could not be established."
  kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" get pods -l "app.kubernetes.io/name=clipp-relay,app.kubernetes.io/instance=$CLIPP_TEST_RELEASE" -o json | ruby -rjson -e '
    pods = JSON.parse(STDIN.read).fetch("items")
    abort "relay Pod still exists: #{pods.map { |p| p.dig("metadata", "name") }.join(", ")}" unless pods.empty?
  ' || die "Wait for every old relay Pod to disappear or investigate node fencing."
}
ensure_pg_restart_permissions() {
  local scripts_json expected_init installed_sts pg_policy
  expected_init=$(cat "$chart_dir/files/postgres/initialize.sh")
  scripts_json=$(kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" get configmap "$pg_sts_name-scripts" -o json) || die "PostgreSQL scripts ConfigMap is missing."
  installed_sts=$(kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" get statefulset "$pg_sts_name" -o json) || die "PostgreSQL StatefulSet is missing."
  pg_policy=$(printf '%s' "$installed_sts" | ruby -rjson -e 'puts JSON.parse(STDIN.read).dig("spec", "template", "spec", "securityContext", "fsGroupChangePolicy")')
  if printf '%s' "$scripts_json" | ruby -rjson -e 'abort "restart guard differs" unless JSON.parse(STDIN.read).dig("data", "initialize.sh").to_s.strip == ARGV.fetch(0).strip' "$expected_init" 2>/dev/null && [[ "$pg_policy" == OnRootMismatch ]]; then
    return 0
  fi
  [[ "$current_phase" == migrating && "$current_initialize" == false && "$current_run_id" == "$db_run_id" ]] || die "PostgreSQL permission repair requires the verified migrating phase and run ID."
  assert_old_relay_absent
  say "The test chart now restores owned PostgreSQL data to mode 0700 after claim/major-version checks and sets fsGroupChangePolicy=OnRootMismatch. The current installation lacks this restart repair."
  say "The same PVC, role credentials, image and migration run ID will be reused. This updates the test chart and restarts its single PostgreSQL Pod."
  confirm "Apply the PostgreSQL permission repair and restart $pg_sts_name-0 in $CLIPP_TEST_KUBE_CONTEXT / $CLIPP_TEST_NAMESPACE?" || die "Permission repair was not applied; the release remains migrating."
  helm --kube-context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" upgrade "$CLIPP_TEST_RELEASE" "$chart_dir" -f "$CLIPP_TEST_VALUES_FILE" -f "$letsencrypt_overlay" --set deployment.phase=migrating --set-string deployment.runId="$db_run_id" --set database.bundled.initialize=false || die "Permission-repair Helm upgrade failed; inspect the release before retrying."
  kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" delete pod "$pg_sts_name-0" --wait=true || die "Could not restart the test PostgreSQL Pod."
  wait_for_pg_pod
}

wait_for_pg_pod() {
  local attempt pod_json state
  for ((attempt=0; attempt<120; attempt++)); do
    pod_json=$(kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" get pod "$pg_sts_name-0" --ignore-not-found -o json) || die "Could not inspect PostgreSQL Pod status."
    if [[ -n "$pod_json" ]]; then
      state=$(printf '%s' "$pod_json" | ruby -rjson -e '
        status = JSON.parse(STDIN.read).fetch("status", {})
        conditions = status.fetch("conditions", [])
        scheduled = conditions.find { |c| c["type"] == "PodScheduled" }
        if scheduled && scheduled["status"] == "False" && scheduled["reason"] == "Unschedulable"
          puts "blocked|#{scheduled.fetch("message", "Pod is unschedulable")}"
        elsif conditions.any? { |c| c["type"] == "Initialized" && c["status"] == "True" }
          puts "initialized"
        else
          init = status.fetch("initContainerStatuses", []).find { |c| c["name"] == "initialize" }
          current = init ? init.fetch("state", {}) : {}
          waiting = current.fetch("waiting", {})
          terminated = current.fetch("terminated", {})
          if terminated.fetch("exitCode", 0) != 0
            puts "failed|initialize exited #{terminated["exitCode"]}: #{terminated.fetch("reason", "Error")}; inspect logs with -c initialize"
          elsif %w[CrashLoopBackOff ImagePullBackOff ErrImagePull CreateContainerConfigError].include?(waiting["reason"])
            puts "failed|initialize: #{waiting["reason"]}; inspect Pod events and logs with -c initialize"
          else
            puts "pending"
          end
        end
      ') || die "Could not interpret PostgreSQL Pod status."
      case "$state" in
        initialized) return 0 ;;
        blocked\|*)
          if [[ "$state" == *"Insufficient cpu"* || "$state" == *"Insufficient memory"* ]] || (( attempt >= 6 )); then
            die "PostgreSQL Pod could not be scheduled: ${state#*|} Initialization has not started."
          fi ;;
        failed\|*) die "PostgreSQL init container failed: ${state#*|}" ;;
      esac
    fi
    sleep 5
  done
  die "PostgreSQL initialization did not complete within 600 seconds; inspect Pod events and logs with -c initialize."
}
wait_for_job_completion() {
  local job_name="$1" max_seconds="$2" attempt job_json state
  for ((attempt=0; attempt<max_seconds/5; attempt++)); do
    job_json=$(kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" get job "$job_name" -o json) || die "Job $job_name is missing or unreadable."
    state=$(printf '%s' "$job_json" | ruby -rjson -e '
      job = JSON.parse(STDIN.read)
      status = job.fetch("status", {})
      if status.fetch("failed", 0).to_i > 0 || status.fetch("conditions", []).any? { |c| c["type"] == "Failed" && c["status"] == "True" }
        puts "failed"
      elsif status.fetch("succeeded", 0).to_i == 1
        puts "complete"
      else
        puts "pending"
      end
    ') || die "Could not read Job $job_name status."
    case "$state" in
      complete) say "Job completed: $job_name"; return 0 ;;
      failed) die "Job $job_name failed. Inspect its Pod and logs; the wizard will not create a replacement automatically." ;;
    esac
    if (( attempt > 0 && attempt % 12 == 0 )); then say "Still waiting for Job $job_name..."; fi
    sleep 5
  done
  die "Job $job_name did not finish within $max_seconds seconds. Inspect it before rerunning."
}

verify_recorded_serving_release() {
  [[ "$current_phase" == serving && "$CLIPP_TEST_KUBE_CONTEXT" == context-couryw6kqaa && "$CLIPP_TEST_NAMESPACE" == relay-portal-test && "$CLIPP_TEST_RELEASE" == clipp-relay-test ]] || die "Installed release values drifted from the reviewed test configuration. Only the recorded serving deployment can resume with newer values."
  require_file "$reviewed_serving_values_file"
  local registered_extension_id
  registered_extension_id=$(printf '%s' "$installed_values_json" | ruby -rjson -rdigest -e '
    payload = File.binread(ARGV.fetch(0))
    abort "recorded serving configuration changed; review its deployment receipt" unless Digest::SHA256.hexdigest(payload) == ARGV.fetch(1)
    expected = JSON.parse(payload)
    actual = JSON.parse(STDIN.read)
    unless actual == expected
      changed = (actual.keys | expected.keys).select { |key| actual[key] != expected[key] }
      abort "installed values differ from the recorded serving deployment: #{changed.join(", ")}"
    end
    abort "recorded deployment is not serving" unless expected.dig("deployment", "phase") == "serving" && expected.dig("deployment", "runId") == "" && expected.dig("database", "bundled", "initialize") == false
    callback = expected.dig("clients", "extensionRedirect").to_s.match(%r{\Ahttps://([a-p]{32})\.chromiumapp\.org/clipp-relay\z})
    abort "recorded Chrome callback is invalid" unless callback
    puts callback[1]
  ' "$reviewed_serving_values_file" "$reviewed_serving_values_sha256") || die "Installed release values drifted from the recorded serving configuration."
  # This changes only the in-process expectations for live checks. The original
  # private values and fingerprint still identify the completed migration Job.
  CLIPP_TEST_VALUES_FILE="$reviewed_serving_values_file"
  CLIPP_TEST_EXTENSION_ID="$registered_extension_id"
  say "Verified the recorded serving deployment: Android callback image, current Chrome callback, and public NLBs. Original migration identity is retained."
}

verify_installed_release() {
  [[ "$current_release_status" == deployed && "$saved_fingerprint" == "$install_fingerprint" ]] || die "An existing Helm release has unreviewed status or ownership: $current_release_status."
  IFS='|' read -r current_phase current_run_id current_initialize <<< "$(release_phase)" || die "Could not inspect installed release phase."
  [[ "$current_phase" == stopped || "$current_phase" == migrating || "$current_phase" == serving ]] || die "Unexpected installed relay phase."
  installed_values_json=$(helm --kube-context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" get values "$CLIPP_TEST_RELEASE" -o json) || die "Could not read the installed release values."
  if printf '%s' "$installed_values_json" | ruby -ryaml -rjson -e '
    actual = JSON.parse(STDIN.read)
    expected = YAML.safe_load(File.read(ARGV.fetch(0)))
    overlay = YAML.safe_load(File.read(ARGV.fetch(1)))
    overlay.each { |key, value| expected[key] = expected.fetch(key, {}).merge(value) }
    expected.fetch("database").fetch("bundled")["initialize"] = (ARGV.fetch(2) == "stopped")
    %w[image public certificates clients transports database credentials journal oci scheduling].each do |key|
      exit 1 unless actual[key] == expected[key]
    end
  ' "$CLIPP_TEST_VALUES_FILE" "$letsencrypt_overlay" "$current_phase"; then
    :
  else
    verify_recorded_serving_release
  fi
  if [[ "$current_phase" == serving ]]; then
    [[ -z "$current_run_id" && "$current_initialize" == false ]] || die "Serving release retains a migration run ID or first-initialization flag."
  fi
  say "Resuming reviewed release in $current_phase phase."
}
verify_completed_bootstrap() {
  [[ -n "$db_run_id" ]] || die "The saved database run ID is missing; cannot verify the earlier bootstrap."
  bootstrap_job="$pg_sts_name-bootstrap-$db_run_id"
  [[ "$(kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" get job "$bootstrap_job" -o jsonpath='{.status.succeeded}')" == 1 ]] || die "The retained PostgreSQL bootstrap Job is not complete."
  kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" get pod "$pg_sts_name-0" -o json | ruby -rjson -e '
    pod = JSON.parse(STDIN.read)
    init = pod.dig("spec", "initContainers").find { |c| c["name"] == "initialize" }
    value = init.fetch("env").find { |e| e["name"] == "CLIPP_INITIALIZE" }
    abort "serving PostgreSQL Pod still permits first initialization" unless value.fetch("value") == "false"
  ' || die "PostgreSQL Pod did not adopt the safe serving template."
  say "Verified the retained PostgreSQL bootstrap Job."
}
verify_completed_migration() {
migration_job_json=$(kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" get job "$migration_job" -o json) || die "Completed migration Job is missing."
printf '%s' "$migration_job_json" | ruby -rjson -e '
  job = JSON.parse(STDIN.read)
  abort "migration Job belongs to another setup" unless job.dig("metadata", "annotations", "clipp-relay-test/install-fingerprint") == ARGV.fetch(0)
  abort "migration Job did not succeed exactly once" unless job.dig("status", "succeeded") == 1
  container = job.dig("spec", "template", "spec", "containers", 0)
  abort "migration Job CPU request differs from the approved 300m" unless container.dig("resources", "requests", "cpu") == "300m"
  abort "migration Job image or command changed" unless container["image"] == ARGV.fetch(1) && container["args"] == ["-command", "migrate", "-config", "/etc/clipp/config.json"]
  volumes = job.dig("spec", "template", "spec", "volumes")
  abort "migration Job Secret mounts changed" unless volumes.find { |v| v["name"] == "db" }.dig("secret", "secretName") == ARGV.fetch(2) && volumes.find { |v| v["name"] == "db-ca" }.dig("secret", "secretName") == ARGV.fetch(3)
' "$install_fingerprint" "$(ruby -ryaml -e 'v=YAML.safe_load(File.read(ARGV[0])); i=v.fetch("image"); puts "#{i.fetch("repository")}@#{i.fetch("digest")}"' "$migration_values_file")" "$db_migration_secret" "$db_ca_secret" || die "Completed migration Job identity differs from the reviewed chart."
migration_logs=$(kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" logs "job/$migration_job" -c migrate --tail=100) || die "Could not verify the completed migration log."
printf '%s\n' "$migration_logs" | ruby -rjson -e '
  records = STDIN.each_line.map { |line| JSON.parse(line) rescue nil }.compact
  abort "migration revision 10 completion record missing" unless records.any? { |r| r["msg"] == "migration complete" && r["revision"] == 10 }
' || die "Migration completion or schema revision could not be verified."
say "The migration Job completed and reported schema revision 10."
}

if [[ "$START_AT" != 16 ]]; then
stage "Check capacity for the 300m isolated test profile"
say "Approved test profile: the application migration Job and serving relay each request 300m CPU. PostgreSQL still requests 400m. CPU limits and memory budgets retain their reviewed values."
say "No worker expansion is required if the current reservations leave a matching Ready node with 300m free. Migration and serving run sequentially. The earlier Terraform capacity plan is not part of this setup path."
assert_minimum_node_cpu
assert_free_relay_cpu
say "The CPU reservation check passed. Kubernetes will enforce memory, storage, taints and other scheduling constraints as the Pods start. Capacity qualification remains deferred."

stage "Review the test release and install or resume"
say "Target: $CLIPP_TEST_KUBE_CONTEXT / $CLIPP_TEST_NAMESPACE, release $CLIPP_TEST_RELEASE, chart commit $(git -C "$CLIPP_TEST_GO_REPO" rev-parse --short HEAD)."
current_release_status=$(release_status) || die "Could not inspect the Helm release in this cluster."
if [[ "$current_release_status" == absent ]]; then
  say "A first install starts with zero relay replicas and a new PostgreSQL claim. Installation requires confirmation below."
else
  say "An existing release was found. Its reviewed deployment values and saved phase will be verified before resuming."
fi
assert_minimum_node_cpu
ruby -ryaml -e 'v=YAML.safe_load(File.read(ARGV.fetch(0))); abort "only a chart-created test PVC is supported" unless v.dig("database", "bundled", "storage", "newClaim", "enabled") == true && v.dig("database", "bundled", "storage", "existingClaim").to_s.empty?' "$CLIPP_TEST_VALUES_FILE" || die "This installer requires the reviewed new-claim test path."
helm template "$CLIPP_TEST_RELEASE" "$chart_dir" -n "$CLIPP_TEST_NAMESPACE" -f "$CLIPP_TEST_VALUES_FILE" -f "$letsencrypt_overlay" | ruby -ryaml -rjson -e '
  docs = YAML.load_stream(STDIN.read).compact
  config = docs.find { |d| d["kind"] == "ConfigMap" && d.dig("metadata", "name") == "#{ARGV.fetch(0)}-clipp-relay-config" }
  abort "rendered relay ConfigMap missing" unless config
  private_port = JSON.parse(config.dig("data", "config.json")).dig("listeners", "private").split(":").last.to_i
  services = docs.select { |d| d["kind"] == "Service" }
  abort "private operations listener exposed by a Service" if services.any? { |s| s.dig("spec", "ports").any? { |p| p["port"] == private_port || p["targetPort"] == private_port || p["targetPort"] == "private" } }
  hosts = docs.select { |d| d["kind"] == "Ingress" }.flat_map { |d| d.dig("spec", "rules").map { |r| r["host"] } }
  abort "exact portal or WSS Ingress missing" unless hosts.include?(ARGV.fetch(1)) && hosts.include?(ARGV.fetch(2))
' "$CLIPP_TEST_RELEASE" "$CLIPP_TEST_PORTAL_HOST" "$CLIPP_TEST_WSS_HOSTNAME" || die "Rendered public hosts or private operations exposure failed review."
if [[ "$current_release_status" == absent ]]; then
  if [[ -n "$saved_fingerprint" ]]; then
    say "A prior install attempt recorded this same fingerprint, but no Helm release or PVC was found by preflight. Rechecking the target before retrying."
  fi
  assert_old_relay_absent
  confirm "Install this stopped test release and initialize its new PostgreSQL claim in the exact target above?" || die "Installation was not started."
  if [[ -z "$saved_fingerprint" ]]; then write_env CLIPP_TEST_INSTALL_FINGERPRINT "$install_fingerprint"; fi
  helm --kube-context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" install "$CLIPP_TEST_RELEASE" "$chart_dir" -f "$CLIPP_TEST_VALUES_FILE" -f "$letsencrypt_overlay" --set deployment.phase=stopped --set-string deployment.runId= --set database.bundled.initialize=true || die "Stopped-phase Helm install failed; inspect release and PVC before rerunning."
  current_phase=stopped
  current_run_id=""
  current_initialize=true
else
  verify_installed_release
fi
if [[ "$current_phase" == stopped ]]; then
  [[ "$current_initialize" == true ]] || die "Stopped release lacks the reviewed first-initialization flag."
  kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" wait --for=jsonpath='{.status.phase}'=Bound "pvc/$pg_sts_name" --timeout=600s || die "The PostgreSQL PVC did not become Bound."
  wait_for_pg_pod
  assert_old_relay_absent
  say "New database claim is Bound; PostgreSQL initialization completed; no relay Pod exists."
  say "The serving-role probe may log a missing role until the next stage completes the database role bootstrap."
fi

stage "Bootstrap distinct PostgreSQL roles"
if [[ "$current_phase" == serving ]]; then
  verify_completed_bootstrap
else
  if [[ "$current_phase" == stopped ]]; then
    assert_old_relay_absent
    if [[ -z "$db_run_id" ]]; then
      db_run_id=$(openssl rand -hex 4)
      write_env CLIPP_TEST_DB_RUN_ID "$db_run_id"
    fi
    require_match "database run ID" "$db_run_id" '^[a-f0-9]{8}$'
    helm --kube-context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" upgrade "$CLIPP_TEST_RELEASE" "$chart_dir" -f "$CLIPP_TEST_VALUES_FILE" -f "$letsencrypt_overlay" --set deployment.phase=migrating --set-string deployment.runId="$db_run_id" --set database.bundled.initialize=false || die "Migration-phase Helm upgrade failed; inspect the release and bootstrap Job."
    current_phase=migrating
    current_run_id="$db_run_id"
    current_initialize=false
  fi
  [[ "$current_phase" == migrating && "$current_initialize" == false && -n "$db_run_id" && "$current_run_id" == "$db_run_id" ]] || die "Installed bootstrap phase or run ID does not match the saved run ID."
  bootstrap_job="$pg_sts_name-bootstrap-$db_run_id"
  wait_for_job_completion "$bootstrap_job" 900
  ensure_pg_restart_permissions
  assert_old_relay_absent
  pg_pod_json=$(kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" get pod "$pg_sts_name-0" -o json) || die "PostgreSQL Pod is missing."
  pod_init_flag=$(printf '%s' "$pg_pod_json" | ruby -rjson -e '
    pod = JSON.parse(STDIN.read)
    abort "PostgreSQL Pod owner differs" unless pod.dig("metadata", "ownerReferences").any? { |o| o["kind"] == "StatefulSet" && o["name"] == ARGV.fetch(0) }
    init = pod.dig("spec", "initContainers").find { |c| c["name"] == "initialize" }
    abort "PostgreSQL init container missing" unless init
    value = init.fetch("env").find { |e| e["name"] == "CLIPP_INITIALIZE" }
    puts value.fetch("value")
  ' "$pg_sts_name") || die "Could not verify the PostgreSQL Pod template."
  if [[ "$pod_init_flag" == true ]]; then
    say "Restarting only the test PostgreSQL Pod to adopt initialize=false after bootstrap."
    kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" delete pod "$pg_sts_name-0" --wait=true || die "PostgreSQL Pod restart failed; inspect its StatefulSet."
  elif [[ "$pod_init_flag" != false ]]; then
    die "PostgreSQL Pod has an unexpected initialization flag."
  fi
  wait_for_pg_pod
  kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" wait --for=condition=Ready "pod/$pg_sts_name-0" --timeout=600s || die "PostgreSQL did not become Ready with the serving role."
  say "Bootstrap completed and PostgreSQL is Ready with initialize=false."
fi

stage "Run the isolated application migration"
if [[ "$current_phase" != serving ]]; then assert_free_relay_cpu; fi
migration_job="$relay_sts_name-migrate-$db_run_id"
[[ -n "$db_run_id" && ${#migration_job} -le 63 ]] || die "Saved migration run ID is missing or Job name is too long."
if [[ "$current_phase" == serving ]]; then
  say "The release is already serving; verifying its retained migration Job before live checks."
else
  assert_old_relay_absent
  deployment_dir="$TEST_DIR/deployment"
  [[ ! -L "$deployment_dir" ]] || die "Deployment working directory cannot be a symbolic link."
  mkdir -p "$deployment_dir"
  chmod 700 "$deployment_dir"
  migration_manifest="$deployment_dir/$migration_job.json"
  [[ ! -L "$migration_manifest" ]] || die "Migration manifest path cannot be a symbolic link."
  generated_manifest=$(mktemp "$deployment_dir/.migration.XXXXXX")
  chmod 600 "$generated_manifest"
    helm template "$CLIPP_TEST_RELEASE" "$chart_dir" -n "$CLIPP_TEST_NAMESPACE" -f "$CLIPP_TEST_VALUES_FILE" -f "$letsencrypt_overlay" --set deployment.phase=migrating --set-string deployment.runId="$db_run_id" --set database.bundled.initialize=false | ruby -ryaml -rjson -e '
      release, namespace, job_name, migration_secret, ca_secret, fingerprint = ARGV
      docs = YAML.load_stream(STDIN.read).compact
      name = "#{release}-clipp-relay"
      sts = docs.find { |d| d["kind"] == "StatefulSet" && d.dig("metadata", "name") == name }
      abort "rendered relay StatefulSet missing" unless sts
      pod = sts.dig("spec", "template", "spec")
      base = pod.fetch("containers").find { |c| c["name"] == "relay" }
      abort "rendered relay container missing" unless base
      migration_resources = Marshal.load(Marshal.dump(base.fetch("resources")))
      migration_resources.fetch("requests")["cpu"] = "300m"
      volumes = pod.fetch("volumes")
      config = volumes.find { |v| v["name"] == "config" }
      ca = volumes.find { |v| v["name"] == "db-ca" }
      abort "rendered config or CA mount missing" unless config && ca && ca.dig("secret", "secretName") == ca_secret
      mounts = base.fetch("volumeMounts").select { |m| %w[config db db-ca].include?(m["name"]) }
      abort "migration mount paths differ from the relay contract" unless mounts.map { |m| m["name"] }.sort == %w[config db db-ca] && mounts.find { |m| m["name"] == "db" }["mountPath"] == "/run/secrets/db"
      db = {"name" => "db", "secret" => {"secretName" => migration_secret, "items" => [{"key" => "username", "path" => "username"}, {"key" => "password", "path" => "password"}]}}
      job = {
        "apiVersion" => "batch/v1", "kind" => "Job",
        "metadata" => {"name" => job_name, "namespace" => namespace,
          "labels" => {"app.kubernetes.io/name" => "clipp-relay-migration", "app.kubernetes.io/instance" => release},
          "annotations" => {"clipp-relay-test/install-fingerprint" => fingerprint}},
        "spec" => {"backoffLimit" => 0, "activeDeadlineSeconds" => 2400,
          "template" => {"metadata" => {"labels" => {"app.kubernetes.io/name" => "clipp-relay-migration", "app.kubernetes.io/instance" => release}},
            "spec" => {"automountServiceAccountToken" => false, "restartPolicy" => "Never",
              "securityContext" => pod.fetch("securityContext"), "nodeSelector" => pod.fetch("nodeSelector", {}),
              "tolerations" => pod.fetch("tolerations", []),
              "containers" => [{"name" => "migrate", "image" => base.fetch("image"), "imagePullPolicy" => base.fetch("imagePullPolicy"),
                "args" => ["-command", "migrate", "-config", "/etc/clipp/config.json"],
                "securityContext" => base.fetch("securityContext"), "resources" => migration_resources, "volumeMounts" => mounts}],
              "volumes" => [config, db, ca]}}}
      }
      puts JSON.pretty_generate(job)
    ' "$CLIPP_TEST_RELEASE" "$CLIPP_TEST_NAMESPACE" "$migration_job" "$db_migration_secret" "$db_ca_secret" "$install_fingerprint" > "$generated_manifest" || die "Could not build the migration-only Job from the rendered chart."
  if [[ -e "$migration_manifest" ]]; then
    cmp -s "$generated_manifest" "$migration_manifest" || die "Saved migration manifest differs from the current reviewed chart."
    rm "$generated_manifest"
  else
    mv "$generated_manifest" "$migration_manifest" || die "Could not save the migration manifest."
  fi
  [[ ! -L "$migration_manifest" && -s "$migration_manifest" ]] || die "Migration Job manifest is not a regular nonempty file."
  migration_job_name=$(kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" get job "$migration_job" --ignore-not-found -o name) || die "Could not inspect the migration Job name."
  if [[ -z "$migration_job_name" ]]; then
    say "The Job requests 300m CPU, uses the pinned relay image and chart ConfigMap, and mounts only the migration login and database CA."
    confirm "Create and run application schema migration Job $migration_job in this test namespace?" || die "Serving transition was not started."
    kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" create -f "$migration_manifest" || die "Migration Job creation failed; inspect the namespace before retrying."
  else
    migration_job_json=$(kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" get job "$migration_job" -o json) || die "Existing migration Job is unavailable."
    printf '%s' "$migration_job_json" | ruby -rjson -e '
      actual = JSON.parse(STDIN.read)
      expected = JSON.parse(File.read(ARGV.fetch(0)))
      abort "existing migration Job belongs to another setup" unless actual.dig("metadata", "annotations", "clipp-relay-test/install-fingerprint") == expected.dig("metadata", "annotations", "clipp-relay-test/install-fingerprint")
      a = actual.dig("spec", "template", "spec")
      e = expected.dig("spec", "template", "spec")
      abort "existing migration Job image or command differs" unless a.dig("containers", 0, "image") == e.dig("containers", 0, "image") && a.dig("containers", 0, "args") == e.dig("containers", 0, "args")
      abort "existing migration Job resource budget differs" unless a.dig("containers", 0, "resources") == e.dig("containers", 0, "resources")
      abort "existing migration Job Secret references differ" unless %w[db db-ca].all? { |name| a.fetch("volumes").find { |v| v["name"] == name }.dig("secret", "secretName") == e.fetch("volumes").find { |v| v["name"] == name }.dig("secret", "secretName") }
      abort "existing migration Job failed" if actual.dig("status", "failed").to_i > 0
    ' "$migration_manifest" || die "Existing migration Job cannot be reused."
    say "Reusing the same reviewed migration Job; no second Job was created."
  fi
fi
wait_for_job_completion "$migration_job" 2400
verify_completed_migration

else
  current_release_status=$(release_status) || die "Could not inspect the saved Helm release."
  verify_installed_release
  [[ "$current_phase" == migrating || "$current_phase" == serving ]] || die "Step 16 requires completed bootstrap and migration; resume from step 12."
  [[ "$current_initialize" == false && -n "$db_run_id" ]] || die "Step 16 requires initialize=false and the saved migration run ID; resume from step 12."
  if [[ "$current_phase" == migrating ]]; then
    [[ "$current_run_id" == "$db_run_id" ]] || die "Installed migration run ID differs from the saved setup."
  fi
  verify_completed_bootstrap
  kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" get pod "$pg_sts_name-0" -o json | ruby -rjson -e '
    pod = JSON.parse(STDIN.read)
    abort "PostgreSQL Pod is not Ready; resume from step 12" unless pod.dig("status", "conditions").to_a.any? { |c| c["type"] == "Ready" && c["status"] == "True" }
  ' || die "The database must be Ready before resuming step 16."
  migration_job="$relay_sts_name-migrate-$db_run_id"
  [[ ${#migration_job} -le 63 ]] || die "Saved migration Job name is too long."
  verify_completed_migration
fi



ensure_public_tls() {
  local tls_work cert_name cert_uid cert_rv request_name request_uid kind owner_name owner_uid
  tls_work=$(mktemp -d $WORK_DIR/clipp-relay-tls-repair.XXXXXX)
  helm template "$CLIPP_TEST_RELEASE" "$chart_dir" -n "$CLIPP_TEST_NAMESPACE" -f "$CLIPP_TEST_VALUES_FILE" -f "$letsencrypt_overlay" --set deployment.phase=serving --set-string deployment.runId= --set database.bundled.initialize=false | ruby -ryaml -rjson -e 'puts JSON.generate(YAML.load_stream(STDIN.read).compact.select { |d| d["kind"] == "Certificate" })' > "$tls_work/expected.json" || die "Could not render the two expected Certificates."
  kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" get certificates,certificaterequests -o json > "$tls_work/actual.json" || die "Could not inspect certificate issuance."
  python3 - "$tls_work/expected.json" "$tls_work/actual.json" "$CLIPP_TEST_RELEASE" "$CLIPP_TEST_NAMESPACE" > "$tls_work/plan.tsv" <<'PY_TLS_PLAN'
import json, sys
expected = json.load(open(sys.argv[1]))
items = json.load(open(sys.argv[2]))['items']
name_key = 'acme.cert-manager.io/http01-override-ingress-name'
temp_key = 'cert-manager.io/issue-temporary-certificate'
if len(expected) != 2:
    raise SystemExit('Expected exactly the portal and WSS Certificates')
for wanted in expected:
    name = wanted['metadata']['name']
    certs = [x for x in items if x['kind'] == 'Certificate' and x['metadata']['name'] == name]
    if len(certs) != 1:
        raise SystemExit('Missing expected Certificate: ' + name)
    cert = certs[0]
    meta, spec = cert['metadata'], cert['spec']
    ann = meta.get('annotations', {})
    if (ann.get('meta.helm.sh/release-name'), ann.get('meta.helm.sh/release-namespace')) != tuple(sys.argv[3:5]):
        raise SystemExit('Certificate Helm ownership differs: ' + name)
    for key in ('secretName', 'dnsNames', 'issuerRef'):
        if spec.get(key) != wanted['spec'][key]:
            raise SystemExit('Certificate target differs: ' + name)
    ready = any(c['type'] == 'Ready' and c['status'] == 'True' for c in cert.get('status', {}).get('conditions', []))
    requests = []
    if not ready:
        for req in items:
            if req['kind'] != 'CertificateRequest':
                continue
            owners = req['metadata'].get('ownerReferences', [])
            if not any(o.get('kind') == 'Certificate' and o.get('uid') == meta['uid'] and o.get('name') == name for o in owners):
                continue
            conditions = req.get('status', {}).get('conditions', [])
            if any(c['type'] == 'Ready' and c['status'] == 'True' for c in conditions):
                continue
            if req['metadata'].get('annotations', {}).get(name_key) == name:
                continue
            if not any(c['type'] == 'Ready' and c['status'] == 'False' and c.get('reason') == 'Pending' for c in conditions):
                raise SystemExit('Request is not safely retryable Pending: ' + req['metadata']['name'])
            requests.append(req)
    if ann.get(name_key) != name or ann.get(temp_key) != 'true' or requests:
        print('certificate', name, meta['uid'], sep='\t')
    for req in requests:
        print('request', req['metadata']['name'], req['metadata']['uid'], name, meta['uid'], sep='\t')
PY_TLS_PLAN
  [[ $? == 0 ]] || die "TLS repair target validation failed; no changes were made."
  if [[ -s "$tls_work/plan.tsv" ]]; then
    say "The test Certificates need in-place HTTP-01 routing and temporary TLS. Their old pending requests will be retried; issued TLS Secrets are retained."
    confirm "Repair only the portal and WSS Certificates and retry their validated pending requests in $CLIPP_TEST_NAMESPACE?" || die "TLS repair was declined."
    while IFS=$'\t' read -r kind cert_name cert_uid owner_name owner_uid; do
      [[ "$kind" == certificate ]] || continue
      kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" get "certificate/$cert_name" -o json > "$tls_work/certificate.json" || die "Certificate changed; inspect fresh issuance state."
      cert_rv=$(python3 - "$tls_work/certificate.json" "$cert_uid" <<'PY_TLS_CERT_RECHECK'
import json, sys
c = json.load(open(sys.argv[1]))
assert c['metadata']['uid'] == sys.argv[2], 'Certificate identity changed'
print(c['metadata']['resourceVersion'])
PY_TLS_CERT_RECHECK
) || die "Certificate changed during review; no annotation was written."
      kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" annotate "certificate/$cert_name" "acme.cert-manager.io/http01-override-ingress-name=$cert_name" cert-manager.io/issue-temporary-certificate=true --overwrite --resource-version="$cert_rv" || die "Could not set the scoped Certificate annotations."
    done < "$tls_work/plan.tsv"
    while IFS=$'\t' read -r kind request_name request_uid owner_name owner_uid; do
      [[ "$kind" == request ]] || continue
      kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" get "certificaterequest/$request_name" -o json > "$tls_work/request.json" || die "Pending request changed; rerun the wizard to inspect fresh issuance state."
      python3 - "$tls_work/request.json" "$request_uid" "$owner_name" "$owner_uid" <<'PY_TLS_RECHECK'
import json, sys
r = json.load(open(sys.argv[1]))
assert r['metadata']['uid'] == sys.argv[2], 'CertificateRequest identity changed'
assert any(o.get('kind') == 'Certificate' and o.get('name') == sys.argv[3] and o.get('uid') == sys.argv[4] for o in r['metadata'].get('ownerReferences', [])), 'Certificate owner changed'
assert any(c['type'] == 'Ready' and c['status'] == 'False' and c.get('reason') == 'Pending' for c in r.get('status', {}).get('conditions', [])), 'Request is no longer Pending; inspect fresh state'
PY_TLS_RECHECK
      [[ $? == 0 ]] || die "Request changed during review; no request was deleted. Rerun to inspect fresh state."
      kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" delete "certificaterequest/$request_name" --wait=false || die "Could not retry the pending request."
    done < "$tls_work/plan.tsv"
  fi
  for cert_name in "$relay_sts_name-portal" "$relay_sts_name-wss"; do
    if ! kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" wait --for=condition=Ready "certificate/$cert_name" --timeout=600s; then
      kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" get challenges -o custom-columns='NAME:.metadata.name,STATE:.status.state,REASON:.status.reason' || true
      die "The public certificate $cert_name is not Ready; inspect the challenge reason above."
    fi
  done
  rm -rf "$tls_work"
}

stage "Verify serving and run live checks"
if [[ "$current_phase" != serving ]]; then
  assert_free_relay_cpu
  assert_old_relay_absent
  confirm "Switch this reviewed release to one serving relay replica after the completed migration?" || die "The release remains in migrating phase."
  helm --kube-context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" upgrade "$CLIPP_TEST_RELEASE" "$chart_dir" -f "$CLIPP_TEST_VALUES_FILE" -f "$letsencrypt_overlay" --set deployment.phase=serving --set-string deployment.runId= --set database.bundled.initialize=false || die "Serving-phase Helm upgrade failed; inspect the release before rerunning."
  current_phase=serving
fi
installed_services_json=$(kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" get services -o json) || die "Could not inspect installed Services."
printf '%s' "$installed_services_json" | ruby -rjson -e '
  services = JSON.parse(STDIN.read).fetch("items").select { |s| s.dig("metadata", "name").start_with?(ARGV.fetch(0) + "-") }
  abort "expected relay Services are missing" unless %w[portal wss].all? { |suffix| services.any? { |s| s.dig("metadata", "name") == ARGV.fetch(0) + "-" + suffix } }
  private_port = ARGV.fetch(1).to_i
  abort "private operations listener exposed by an installed Service" if services.any? { |s| s.dig("spec", "ports").any? { |p| p["port"] == private_port || p["targetPort"] == private_port || p["targetPort"] == "private" } }
' "$relay_sts_name" "$(ruby -ryaml -e 'v=YAML.safe_load(File.read(ARGV[0])); puts(v.dig("listeners", "privatePort") || 8081)' "$CLIPP_TEST_VALUES_FILE")" || die "Installed Service exposure differs from the reviewed chart."
installed_ingress_json=$(kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" get ingress "$relay_sts_name-portal" "$relay_sts_name-wss" -o json) || die "Could not inspect installed HTTPS Ingresses."
printf '%s' "$installed_ingress_json" | ruby -rjson -e '
  ingresses = JSON.parse(STDIN.read).fetch("items")
  expected = {"#{ARGV.fetch(0)}-portal" => ARGV.fetch(1), "#{ARGV.fetch(0)}-wss" => ARGV.fetch(2)}
  expected.each do |name, host|
    ingress = ingresses.find { |item| item.dig("metadata", "name") == name }
    abort "Ingress #{name} missing or wrong host" unless ingress && ingress.dig("spec", "rules").map { |r| r["host"] } == [host]
  end
' "$relay_sts_name" "$CLIPP_TEST_PORTAL_HOST" "$CLIPP_TEST_WSS_HOSTNAME" || die "Installed Ingress hosts differ from the reviewed target."
ensure_public_tls
pg_sts_json=$(kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" get statefulset "$pg_sts_name" -o json) || die "PostgreSQL StatefulSet is missing."
pg_claim=$(printf '%s' "$pg_sts_json" | ruby -rjson -e 's=JSON.parse(STDIN.read); v=s.dig("spec","template","spec","volumes").find{|x|x["name"]=="data"}; abort "database PVC reference missing" unless v; puts v.dig("persistentVolumeClaim","claimName")') || die "Could not read the installed PostgreSQL PVC reference."
[[ -n "$pg_claim" ]] || die "Installed PostgreSQL PVC name is empty."
pg_claim_phase=$(kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" get pvc "$pg_claim" -o jsonpath='{.status.phase}') || die "Database PVC $pg_claim is missing."
[[ "$pg_claim_phase" == Bound ]] || die "Database PVC $pg_claim is $pg_claim_phase, not Bound."
relay_sts_json=$(kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" get statefulset "$relay_sts_name" -o json) || die "Relay StatefulSet is missing."
printf '%s' "$relay_sts_json" | ruby -rjson -e '
  sts = JSON.parse(STDIN.read)
  container = sts.dig("spec", "template", "spec", "containers").find { |c| c["name"] == "relay" }
  abort "installed relay image differs from reviewed digest" unless container && container["image"] == ARGV.fetch(0)
  abort "installed relay CPU request differs from the approved 300m" unless container.dig("resources", "requests", "cpu") == "300m"
' "$(ruby -ryaml -e 'v=YAML.safe_load(File.read(ARGV[0])); i=v.fetch("image"); puts "#{i.fetch("repository")}@#{i.fetch("digest")}"' "$CLIPP_TEST_VALUES_FILE")" || die "Relay image verification failed."
for sts_name in "$pg_sts_name" "$relay_sts_name"; do
  # Both chart StatefulSets use OnDelete; rollout status rejects that strategy.
  kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" wait --for=jsonpath='{.status.readyReplicas}'=1 "statefulset/$sts_name" --timeout=900s || die "StatefulSet $sts_name did not reach one Ready replica; inspect its Pod."
  kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" wait --for=condition=Ready "pod/$sts_name-0" --timeout=900s || die "Pod $sts_name-0 did not become Ready."
  kubectl --context "$CLIPP_TEST_KUBE_CONTEXT" -n "$CLIPP_TEST_NAMESPACE" get "statefulset/$sts_name" "pod/$sts_name-0" -o json | ruby -rjson -e '
    items = JSON.parse(STDIN.read).fetch("items")
    sts = items.find { |item| item["kind"] == "StatefulSet" && item.dig("metadata", "name") == ARGV.fetch(0) }
    pod = items.find { |item| item["kind"] == "Pod" && item.dig("metadata", "name") == ARGV.fetch(0) + "-0" }
    abort "StatefulSet or Pod missing" unless sts && pod
    abort "StatefulSet is not at one desired and Ready replica" unless sts.dig("spec", "replicas") == 1 && sts.dig("status", "readyReplicas") == 1
    abort "StatefulSet controller has not observed the current generation" unless sts.dig("status", "observedGeneration").to_i >= sts.dig("metadata", "generation").to_i
    abort "Pod owner differs from the expected StatefulSet" unless pod.dig("metadata", "ownerReferences").to_a.any? { |owner| owner["kind"] == "StatefulSet" && owner["uid"] == sts.dig("metadata", "uid") && owner["controller"] == true }
    revision = sts.dig("status", "updateRevision")
    abort "Ready Pod still uses an older OnDelete template; review its manual serving transition" unless revision && pod.dig("metadata", "labels", "controller-revision-hash") == revision
    abort "Pod is terminating or not Ready" if pod.dig("metadata", "deletionTimestamp") || !pod.dig("status", "conditions").to_a.any? { |c| c["type"] == "Ready" && c["status"] == "True" }
  ' "$sts_name" || die "StatefulSet $sts_name readiness or active template verification failed."

  say "Ready StatefulSet: $sts_name (1/1)."
done
say "The database PVC is Bound and both public certificates are Ready."
check_url "$CLIPP_TEST_PORTAL_ORIGIN/" || die "The HTTPS portal is not reachable with trusted TLS."
check_url "https://$CLIPP_TEST_WSS_HOSTNAME/" || die "The WSS host TLS endpoint is not reachable with trusted TLS."
say "Both HTTPS hosts responded over trusted TLS from this machine."
step "Open the portal from a second network or device and verify the exact certificate/host; the local curl check alone is not external reachability proof."
confirm "Is the portal reachable from an independent client network?" || die "Fix external reachability before client login."
CLIPP_TEST_DISCOVERY_URL="$CLIPP_TEST_PORTAL_ORIGIN/v1/relay"
write_env CLIPP_TEST_DISCOVERY_URL "$CLIPP_TEST_DISCOVERY_URL"

stage "Sign in and approve the ordinary test account"
open_url "$CLIPP_TEST_PORTAL_ORIGIN/auth/login"
step "In one browser profile, sign in as $CLIPP_TEST_USER_EMAIL. The portal should show Pending."
step "In a separate browser profile, sign in as $CLIPP_TEST_ADMIN_EMAIL and open $CLIPP_TEST_PORTAL_ORIGIN/admin."
confirm "Do you approve moving this isolated test account from Pending to Active?" || die "Leave the account Pending until approved."
step "Select the pending test account, choose Approve, assign the seeded Baseline plan, keep reason routine_administration, and Apply."
step "Return to the ordinary account's portal profile and confirm Active status and the assigned allowance."
confirm "Is $CLIPP_TEST_USER_EMAIL Active with the Baseline plan?" || die "The relay account is not approved yet."

stage "Pair two Electron profiles and transfer a clip"
say "Use two distinct Clipp Electron profiles or devices; never reuse one Device Identity as both endpoints."
step "On each profile: Network → Relays → Add relay → Managed; enter $CLIPP_TEST_DISCOVERY_URL as the HTTPS discovery URL."
step "Choose Log in from each relay card and complete browser authorization for the approved test account."
step "On profile A choose Show my QR; on profile B choose Scan QR or paste the pairing text, then approve the pairing request."
step "Wait for both relay cards to show Ready, send a fresh text clip, and confirm it arrives on the paired profile through the managed relay."
confirm "Did both profiles become Ready and transfer a clip over this relay?" || die "Keep the setup open; pairing or transfer still needs investigation."

stage "Record Android and Chrome runtime evidence when available"
step "For Chrome, use the rebuilt extension whose ID is $CLIPP_TEST_EXTENSION_ID; add $CLIPP_TEST_DISCOVERY_URL and authorize through its exact chromiumapp callback."
step "For Android, use an actual supported device/browser; add the same discovery URL and authorize through clipp-relay://oauth/callback."
step "Pair each with another device, force WSS and WebRTC Direct separately when the target exposes both, and record browser, OS, device and transport evidence."
if ! confirm "Did Chrome and Android each complete real authorization and relayed transfer?"; then
  SKIPPED+=("Chrome and/or Android real-runtime acceptance; record which device, callback or transport remains unavailable")
fi
say "Share only $ENV_FILE, the values-file path and non-secret runtime evidence with the implementation agent. Keep all Secret file contents private."
finish
